import sys
import platform

if sys.maxsize < 2**31:
    raise RuntimeError('64 bit system is required')

_arch = platform.machine().lower()

if sys.platform.startswith('linux'):
    if _arch not in ('x86_64', 'amd64'):
        raise RuntimeError(
            f'openseespylinux requires x86_64, but this machine is {platform.machine()}')
    try:
        from openseespylinux.opensees import *
    except Exception as e:
        raise RuntimeError(f'Failed to import openseespy on Linux: {e}')

elif sys.platform.startswith('win'):
    if _arch not in ('x86_64', 'amd64'):
        raise RuntimeError(
            f'openseespywin requires AMD64, but this machine is {platform.machine()}')
    try:
        from openseespywin.opensees import *
    except Exception as e:
        raise RuntimeError(f'Failed to import openseespy on Windows: {e}')

elif sys.platform.startswith('darwin'):
    if _arch != 'arm64':
        raise RuntimeError(
            f'openseespymac requires arm64 (Apple Silicon), but this machine is {platform.machine()}')
    try:
        from openseespymac.opensees import *
    except Exception as e:
        raise RuntimeError(f'Failed to import openseespy on macOS: {e}')

else:
    raise RuntimeError(f'{sys.platform} ({platform.machine()}) is not supported')
